import{_ as t,h as o,i as e,c as n,v as l,p as s,x as r,m as h,e as m,S as p}from"./chunks/framework.Dvtg8yj2.js";const L=JSON.parse('{"title":"氢气流 Dynamic Gas Lock 防污染","description":"","frontmatter":{"title":"氢气流 Dynamic Gas Lock 防污染","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/euv-hydrogen-dgl.md","filePath":"llm/euv-hydrogen-dgl.md","lastUpdated":1788454257000}'),c={name:"llm/euv-hydrogen-dgl.md"};function d(E,a,u,A,B,D){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="氢气流-dynamic-gas-lock-防污染" tabindex="-1">氢气流 Dynamic Gas Lock 防污染 <a class="header-anchor" href="#氢气流-dynamic-gas-lock-防污染" aria-label="Permalink to &quot;氢气流 Dynamic Gas Lock 防污染&quot;">​</a></h1><div class="epigraph"><p>氢气流与动态气锁把光源碎屑挡在扫描腔之外，并靠氢自由基原位清除锡污染。</p><footer>—— 改写自 ASML 公开材料；污染化学见 Bakshi, EUV Lithography</footer></div><p>13.5 nm 光路里没有可以随便换的空气窗。<a href="/llm/euv-lpp-tin">LPP</a> 每秒喷出数万次锡等离子体，离子、中性锡和碳氢残余只要淀积在<a href="/llm/euv-multilayer-mirror">多层膜</a>上，反射率就掉、光瞳就变形。量产机把氢（H₂）既当缓冲气体，又当清洗剂：EUV 光子把 H₂ 解离成自由基，H 与 Sn 生成挥发性 SnH₄，与碳生成 CH₄，再被抽走。动态气锁（Dynamic Gas Lock, DGL）用差压气流在光源舱与扫描舱、以及若干真空分区之间形成单向帘，让光子过、让碎屑不过。本篇写氢化学与气锁几何，不重写收集镜抛光。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>污染有三条并行的路。第一，锡碎屑镀到收集镜，带内反射率下降，IF 功率掉。第二，残余碳氢在 EUV 下裂解，碳膜在投影镜和掩模多层膜上生长，对比与剂量均匀性一起坏。第三，氧化和水汽攻击帽层与硅层，周期和应力漂移，波前跟着走。真空泵只能降低本底，不能挡住等离子体源持续注入的质量流，也不能把已经镀上的锡「抽」下来。</p><p>还要满足互相打架的压力：光源舱需要足够氢密度来减速离子、刻蚀锡；<a href="/llm/zeiss-euv-optics">投影物镜</a>需要高真空以免沿程吸收和碳化；硅片与掩模台有自己的放气和运动约束。一块腔体一个压力做不到。必须分区，并用气流而不是固体窗来衔接——固体窗在 13.5 nm 是挡板。</p><h3 id="为什么是氢而不是惰性气体" tabindex="-1">为什么是氢而不是惰性气体 <a class="header-anchor" href="#为什么是氢而不是惰性气体" aria-label="Permalink to &quot;为什么是氢而不是惰性气体&quot;">​</a></h3><p>氦、氩可以当缓冲，把离子平均自由程打短，但它们不把锡变成可抽走的氢化物。锡会在镜面累积，只能靠换镜或离线清洗。氢的独特处是化学反应通道：</p> \\[\\mathrm{Sn} + 4\\mathrm{H} \\rightarrow \\mathrm{SnH_4},\\qquad \\mathrm{C} + 4\\mathrm{H} \\rightarrow \\mathrm{CH_4}. \\]<p>自由基 H 主要来自 EUV 光解离和等离子体边缘，不是靠把整腔加热到热裂解温度。惰性缓冲可以辅助减速，量产公开叙述的核心清洗剂是氢。代价是氢会攻击不兼容的帽层、引起氢脆或起泡，镜面材料与气锁流量必须一起合格。</p><p><span class="marginnote">DGL 不是「氢气氛浸没光刻」。硅片侧没有液体，氢也不参与成像折射率。气锁的光学厚度必须薄到带内吸收可接受，又厚到分子扩散把锡挡回去——这是流量、缝几何和泵速的平衡，不是把扫描腔灌成一个大气压的氢气。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>光源舱维持较高的氢分压，收集镜浸泡在可刻蚀的自由基环境里。朝向 IF 的通道做成窄缝加逆向或横向氢气流，形成 DGL：下游压力低、上游压力高，净流指向光源或旁路泵口，锡蒸气的扩散平均自由程被气流吹回。扫描腔、掩模腔、硅片腔各自有泵组和气体帘，避免光源脉冲把压力波打进 POB。</p><p>流量是动态的：曝光时 EUV 本身在造自由基，停光时清洗速率下降，有时要维持辅助解离或接受暂时不能清洗。收集镜温度、氢流量和 IF 功率构成闭环——流量过大，沿程吸收吃掉带内功率；过小，锡累积。ASML 公开材料把这套系统写成光源与扫描机集成的一部分，而不是外挂过滤器。</p><h3 id="分区真空与差动抽气" tabindex="-1">分区真空与差动抽气 <a class="header-anchor" href="#分区真空与差动抽气" aria-label="Permalink to &quot;分区真空与差动抽气&quot;">​</a></h3><p>典型分区是：等离子体附近（相对「脏」、氢多）→ DGL → IF 管道 → 照明与投影（更干净）→ 掩模与硅片台。每一级差动抽气，像加速器束线的差分孔。缝太宽，气锁失效；太窄，挡光并增加热与对准敏感。工件台在扫，气锁几何还不能碰运动包络。氢的抽速、安全性（爆燃极限之外的高真空稀释）和泵的耐锡、耐碳能力，属于工厂设施而不只是光学设计。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>离子减速：氢分子把高能锡离子的动能通过碰撞降下来，减轻溅射产额。化学清除：落到镜面的 Sn 与 C 被 H 刻成气体，多层膜帽层（如钌）要在刻锡的同时尽量不被氧化或剥蚀。碳的来源往往不是锡滴，而是真空润滑、电缆放气、光刻胶除气和残留有机物；EUV 是高效的裂解灯。因此 DGL 既挡源，也逼整机材料清单变成「EUV 兼容真空」。</p><p>光子仍走直线穿过气帘。吸收截面使氢柱密度变成透过率项 \\(T_{\\mathrm{gas}}\\)，直接出现在 IF 功率账里。气锁设计是在 \\(T_{\\mathrm{gas}}\\) 与挡锡效率之间取点，而不是把污染降到实验室本底。投影镜一旦碳化，清洗窗口比收集镜窄：过激的氢或氧清洗会改多层膜，波前永久坏。策略往往是「收集镜可牺牲地洗，POB 靠防胜于洗」。</p><p><span class="marginnote">不要把氢刻蚀理解成对微滴撞击无差别有效。高速液滴造成的机械损伤和局部溅射坑，化学反应补不回去。DGL 的首要任务是减少到达下游的质量流；收集镜寿命仍要靠预脉冲碎屑谱、磁场抑制和定期维护。</span></p><h3 id="与-pellicle、胶和随机效应的交界" tabindex="-1">与 pellicle、胶和随机效应的交界 <a class="header-anchor" href="#与-pellicle、胶和随机效应的交界" aria-label="Permalink to &quot;与 pellicle、胶和随机效应的交界&quot;">​</a></h3><p>掩模侧若有 <a href="/llm/euv-pellicle">pellicle</a>，薄膜本身会放气、会拦截颗粒，但也改变局部热和氢到达掩模多层膜的路径。硅片侧光刻胶在 EUV 下出气，是碳源之一；剂量提高以对抗<a href="/llm/euv-stochastics">随机效应</a>时，出气和镜面碳生长可能一起升。污染控制因此与工艺剂量、胶化学绑定，不是光源舱的局部卫生问题。</p>',22)),(e(),s(p,null,{default:r(()=>[m(i,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22LPP%20%E5%85%89%E6%BA%90%E8%88%B1%20%E9%AB%98%20H2%22%5D%20--%3E%20DGL%5B%22Dynamic%20Gas%20Lock%20%E6%B0%A2%E6%B0%94%E6%B5%81%22%5D%0A%20%20DGL%20--%3E%20IF%5B%22%E4%B8%AD%E9%97%B4%E7%84%A6%E7%82%B9%E9%80%9A%E9%81%93%22%5D%0A%20%20IF%20--%3E%20POB%5B%22%E6%8A%95%E5%BD%B1%E8%85%94%20%E9%AB%98%E7%9C%9F%E7%A9%BA%22%5D%0A%20%20SRC%20--%3E%20SN%5B%22%E9%94%A1%E7%A2%8E%E5%B1%91%2F%E7%A6%BB%E5%AD%90%22%5D%0A%20%20SN%20--%3E%20DGL%0A%20%20DGL%20--%3E%20PUMP%5B%22%E5%B7%AE%E5%8A%A8%E6%8A%BD%E6%B0%94%20SnH4%20CH4%22%5D%0A%20%20POB%20--%3E%20OPT%5B%22%E5%A4%9A%E5%B1%82%E8%86%9C%E4%BF%9D%E6%8C%81%E5%8F%8D%E5%B0%84%E7%8E%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>DGL 不增加 NA，不缩短波长，不消除光子散粒噪声。它只让光学合同在时间上可维持。关氢可以提高瞬时透过率，几小时后收集镜就脏到产能崩溃。开太大则 IF 功率被气体吃掉，激光白烧。量产窗口是「够洗、够挡、还留得出光」。</p><p>公开材料不会给出缝宽和 SCCM 流量。写清楚机制即可：氢自由基刻锡/碳、差压气帘代替固体窗、分区真空。不要把同步辐射束线的差分抽气或蚀刻机的远程等离子体清洗直接当成 NXE 的 DGL 图纸。Bakshi 书提供碳污染与氢清洗的物理图像；机台级实现以 ASML 公开架构为准。</p><p><span class="marginnote">安全与设施常被技术文省略：大量氢、真空泵、锡氢化物毒性与排气处理是工厂设计的一部分。光学文章可以不展开规范条款，但不要暗示「开一瓶氢气对着镜子吹」就是动态气锁。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EUV 多层膜的寿命由锡、碳、氧污染决定，真空泵单独不够。</li><li>氢自由基把 Sn、C 变成可抽走的 SnH₄、CH₄，是量产原位清洗通道。</li><li>Dynamic Gas Lock 用差压氢气流当无形窗，隔开光源舱与扫描腔。</li><li>气柱密度进入带内透过率，流量是清洗与出光的折中。</li><li>收集镜以洗为主，投影物镜以防为主，帽层化学必须兼容氢。</li><li>微滴机械损伤不能单靠氢消除；碎屑谱仍要在光源侧控制。</li><li>出处：ASML 公开材料；Bakshi, <em>EUV Lithography</em>。</li></ul>',6))])}const f=t(c,[["render",d]]);export{L as __pageData,f as default};
